const b = $json.body || $json;
const to = String(b.whatsapp || b.to || '').trim();
const ticket = String(b.ticket || '').trim();
const estado = String(b.estado || 'listo').trim();
const negocio = String(b.negocio || '').trim();
const msgs = {
  nuevo: `Pedido ${ticket} recibido${negocio ? ' en ' + negocio : ''}. Te avisamos cuando esté listo.`,
  preparando: `Pedido ${ticket}: lo estamos preparando.`,
  listo: `Pedido ${ticket}: ¡listo! Ya podés pasar / te lo enviamos.`,
  entregado: `Pedido ${ticket}: marcado como entregado. Gracias.`,
  cancelado: `Pedido ${ticket}: cancelado. Si fue un error, escribinos.`
};
const texto = msgs[estado] || msgs.listo;
if (!to) return [{ json: { ok: false, error: 'falta whatsapp', texto } }];
return [{ json: {
  ok: true,
  sistema: '08-cola-pedidos-wasap',
  etapa: 'aviso',
  to, ticket, estado, texto,
  status: 'draft_ready',
  todo: 'TODO_CREDENCIAL: Meta Cloud API send message',
  at: new Date().toISOString()
}}];
